            const address = position.market.params.collateralToken;
            let exposure = this.collateralAllocations.get(address);
            if (!exposure)
                this.collateralAllocations.set(address, (exposure = {
                    address,
                    lltvs: new Set(),
                    oracles: new Set(),
                    markets: new Set(),
                    proportion: 0n,
                }));
